mapper.select:
SELECT id, user_id, measurement_type, measurement_id, severity, message, status FROM t_health_alert  AND id = #{id}
 AND user_id = #{userId}
 AND measurement_type LIKE CONCAT('%', #{measurementType}, '%')
 AND measurement_id = #{measurementId}
 AND severity LIKE CONCAT('%', #{severity}, '%')
 AND status LIKE CONCAT('%', #{status}, '%') ORDER BY id DESC
